package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/pmezard/go-difflib/difflib"
)

func main() {
	flagUsage := "usage: diff-tool <file1> <file2>\n  Computes and displays a unified diff between two files.\n  Use '-' for either argument to read from stdin."

	flag.CommandLine.Usage = func() {
		fmt.Fprintln(os.Stderr, flagUsage)
		flag.CommandLine.PrintDefaults()
	}

	flag.Parse()

	args := flag.Args()
	if len(args) < 2 {
		fmt.Fprintln(os.Stderr, "Error: two arguments required")
		flag.Usage()
		os.Exit(1)
	}

	file1Path := args[0]
	file2Path := args[1]

	text1, err := readFile(file1Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading %s: %v\n", file1Path, err)
		os.Exit(1)
	}

	text2, err := readFile(file2Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading %s: %v\n", file2Path, err)
		os.Exit(1)
	}

	diff := computeUnifiedDiff(text1, text2, file1Path, file2Path)
	fmt.Print(diff)
}

func readFile(path string) (string, error) {
	var r io.Reader
	if path == "-" {
		r = os.Stdin
	} else {
		f, err := os.Open(path)
		if err != nil {
			return "", err
		}
		defer f.Close()
		r = f
	}
	return io.ReadAll(r)
}

func computeUnifiedDiff(text1, text2, name1, name2 string) string {
	lines1 := strings.Split(text1, "\n")
	lines2 := strings.Split(text2, "\n")

	// Remove trailing empty string from split if text ends with newline
	if len(lines1) > 0 && lines1[len(lines1)-1] == "" {
		lines1 = lines1[:len(lines1)-1]
	}
	if len(lines2) > 0 && lines2[len(lines2)-1] == "" {
		lines2 = lines2[:len(lines2)-1]
	}

	diff := difflib.UnifiedDiff{
		A:        difflib.SplitLines(text1),
		B:        difflib.SplitLines(text2),
		FromFile: name1,
		ToFile:   name2,
		Context:  3,
	}

	result, err := diff.GetUnifiedDiffString()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error computing diff: %v\n", err)
		os.Exit(1)
	}
	return result
}

package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/pmezard/go-difflib/difflib"
)

func main() {
	flag.Usage = func() {
		fmt.Fprintln(os.Stderr, "usage: diff-tool <file1> <file2>")
		fmt.Fprintln(os.Stderr, "  Computes and displays a unified diff between two files.")
		fmt.Fprintln(os.Stderr, "  Use '-' for either argument to read from stdin.")
		flag.CommandLine.PrintDefaults()
	}

	flag.Parse()

	args := flag.Args()
	if len(args) < 2 {
		fmt.Fprintln(os.Stderr, "Error: two arguments required")
		flag.Usage()
		os.Exit(1)
	}

	text1, err := readFile(args[0])
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading %s: %v\n", args[0], err)
		os.Exit(1)
	}

	text2, err := readFile(args[1])
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading %s: %v\n", args[1], err)
		os.Exit(1)
	}

	diff := difflib.UnifiedDiff{
		A:        difflib.SplitLines(text1),
		B:        difflib.SplitLines(text2),
		FromFile: args[0],
		ToFile:   args[1],
		Context:  3,
	}

	result, err := diff.GetUnifiedDiffString()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error computing diff: %v\n", err)
		os.Exit(1)
	}
	fmt.Print(result)
}

func readFile(path string) (string, error) {
	if path == "-" {
		return io.ReadAll(os.Stdin)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	// Remove trailing newline to avoid extra empty line in diff
	return strings.TrimRight(string(data), "\n"), nil
}

